import { lazy, Suspense, useState } from 'react';

// Heavy, opened rarely -> split
const AdminPanel = lazy(() => import('./AdminPanel'));
const ChartEditor = lazy(() => import('./ChartEditor'));

function App() {
  const [tab, setTab] = useState('home');

  return (
    <Layout>
      {/* Shell renders immediately; only the active pane suspends */}
      <Tabs onChange={(t) => setTab(t)} onMouseEnter={preloadFor(t)} />

      <ErrorBoundary fallback={(err, retry) => <ChunkError retry={retry} />}>
        <Suspense fallback={<PaneSkeleton />}>
          {tab === 'home' && <Home />}
          {tab === 'admin' && <AdminPanel />}
          {tab === 'charts' && <ChartEditor />}
        </Suspense>
      </ErrorBoundary>
    </Layout>
  );
}

// Preload on hover: start the chunk download before the click
function preloadFor(tab) {
  if (tab === 'admin') import('./AdminPanel');       // same cached module promise
  if (tab === 'charts') import('./ChartEditor');
}

// Retry after a failed chunk load (stale HTML referencing old chunks):
// bump a key on the lazy factory so React retries the import
const loadChart = () => import('./ChartEditor');
function ChartWithRetry({ attempt }) {
  const LazyChart = useMemo(() => lazy(() => loadChart().catch((e) => {
    window.location.reload();                        // honest recovery for stale chunks
    throw e;
  })), [attempt]);
  return <Suspense fallback={<Skeleton />}><LazyChart /></Suspense>;// }

